        "title": "Luyện nghe bài 14: Idiomatic English in the Workplace",
        "transcript": "Hello everyone! My name is Anna. I am 21 years old and I currently live in London. I am a university student studying languages. Today, I am very excited to share my experience with Idiomatic English in the Workplace. In my daily routine, I frequently use the word \"Touch base\" when talking with friends. Yesterday afternoon, I spent one hour practicing \"Cut corners\" with my classmates. In addition, knowing how to use \"Hit the ground running\" correctly helps me communicate much more naturally. I believe that practicing for fifteen minutes every day is the best secret to becoming confident. Thank you very much for listening!",
        "audioUrl": null,
        "questions": "[{\"question\":\"What is the speaker's name in the audio?\",\"options\":[\"Anna\",\"Emma\",\"Sarah\",\"Laura\"],\"correctAnswer\":\"Anna\",\"explanation\":\"The audio opens with the introduction: \\\"My name is Anna.\\\"\"},{\"question\":\"How old is the speaker and where does she live?\",\"options\":[\"23 years old, living in Bristol\",\"21 years old, living in London\",\"22 years old, living in Manchester\",\"20 years old, living in Edinburgh\"],\"correctAnswer\":\"21 years old, living in London\",\"explanation\":\"In the audio, the speaker says: \\\"I am 21 years old and I currently live in London.\\\"\"},{\"question\":\"What is the speaker's current occupation or role?\",\"options\":[\"University student studying languages\",\"Part-time language peer tutor\",\"Graduate teaching assistant in linguistics\",\"Intern at an international cultural exchange center\"],\"correctAnswer\":\"University student studying languages\",\"explanation\":\"The speaker clearly states: \\\"I am a university student studying languages.\\\"\"},{\"question\":\"Which vocabulary word did the speaker practice yesterday afternoon?\",\"options\":[\"Touch base\",\"Hit the ground running\",\"On the same page\",\"Cut corners\"],\"correctAnswer\":\"Cut corners\",\"explanation\":\"The speaker mentions: \\\"Yesterday afternoon, I spent one hour practicing 'Cut corners' with my classmates.\\\"\"},{\"question\":\"According to the speaker, what is the best secret to becoming confident?\",\"options\":[\"Writing complex essays before practicing basic conversation\",\"Memorizing fifty words without speaking practice\",\"Reviewing grammar rules once a month\",\"Practicing for fifteen minutes every day\"],\"correctAnswer\":\"Practicing for fifteen minutes every day\",\"explanation\":\"The speaker recommends: \\\"practicing for fifteen minutes every day is the best secret to becoming confident.\\\"\"}]"
