        "explanation": "Ngữ pháp nâng cao B2: Handling Q&A Sessions with Confidence. Dạng khẳng định dùng để diễn đạt sự thật, thói quen hoặc thông tin cơ bản liên quan đến \"Handling Q&A Sessions with Confidence\".",
